```python
import os
from sklearn.linear_model import SGDClassifier  # Example model

class ModelTrainer:
    def __init__(self, model_dir):
        self.model_dir = model_dir

    def start_training(self):
        print("Start training..")

    def fit(self, X, y):
        try:
            self.model = SGDClassifier().fit(X, y)
            return True
        except Exception as e:
            print(f"Error during training: {e}")
            return False

    def save_model(self):
        if self.model is not None:
            try:
                model_path = os.path.join(self.model_dir, "final_model.pkl")
                import pickle
                with open(model_path, 'wb') as file:
                    pickle.dump(self.model, file)
                print("Training done, final model saved")
            except Exception as e:
                print(f"Error while saving model: {e}")
        else:
            print("No model to save")

# Create an instance of ModelTrainer
model_trainer = ModelTrainer(model_dir="models/")

# Sample input data
X = [[0], [1], [2], [3]]
y = [0, 1, 2, 3]

# Start training, fit the model, and save the model
model_trainer.start_training()
if model_trainer.fit(X, y):
    model_trainer.save_model()
else:
    print("Failed to fit the model")
```

This solution creates a `ModelTrainer` class that manages the training and saving of a machine learning model. It includes error handling and demonstrates how to use the class to train a simple linear classifier and save the model.

